import { create } from 'zustand';
import { KDSOrder } from '../types/kds';

interface KDSState {
    orders: Record<string, KDSOrder>;

    addOrUpdateOrder: (order: KDSOrder) => void;
    removeOrder: (orderId: string) => void;
    updateOrderStage: (orderId: string, stage: string) => void;
    markDelayed: (orderId: string, reason?: string) => void;
    delayOrder: (orderId: string, additionalMinutes: number, reason?: string) => void;
}

export const useKDSStore = create<KDSState>((set) => ({
    orders: {},

    addOrUpdateOrder: (order) =>
        set((state) => ({
            orders: {
                ...state.orders,
                [order.id]: order, // idempotent replacement
            },
        })),

    removeOrder: (orderId) =>
        set((state) => {
            const newOrders = { ...state.orders };
            delete newOrders[orderId];
            return { orders: newOrders };
        }),

    updateOrderStage: (orderId, stage) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const now = new Date();
            let updates: Partial<KDSOrder> = {
                stage,
                stageStartedAt: now.toISOString(),
            };

            // Workflow automation: If starting preparation, ensure prepTime and ETA are set
            if (stage === 'Preparation') {
                const prepTime = order.prepTimeMinutes || 10;
                const createdAt = new Date(order.createdAt);
                createdAt.setMinutes(createdAt.getMinutes() + prepTime);

                updates = {
                    ...updates,
                    prepTimeMinutes: prepTime,
                    estimatedReadyTime: createdAt.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    })
                };
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        ...updates,
                    },
                },
            };
        }),

    markDelayed: (orderId, reason) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        isDelayed: true,
                        delayReason: reason,
                    },
                },
            };
        }),

    delayOrder: (orderId: string, additionalMinutes: number, reason?: string) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            // Safe ETA update logic
            let newETA = order.estimatedReadyTime;
            try {
                const parts = order.estimatedReadyTime.split(':').map(Number);
                const hrs = parts[0];
                const mins = parts[1];
                if (hrs !== undefined && mins !== undefined && !isNaN(hrs) && !isNaN(mins)) {
                    const date = new Date();
                    date.setHours(hrs);
                    date.setMinutes(mins + additionalMinutes);

                    newETA = date.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    });
                }
            } catch (e) {
                console.error('Failed to update ETA:', e);
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        prepTimeMinutes: (order.prepTimeMinutes || 0) + additionalMinutes,
                        estimatedReadyTime: newETA,
                        isDelayed: true,
                        delayReason: reason || order.delayReason,
                    },
                },
            };
        }),
}));
