import { KDSOrder, SLAState } from '../types/kds';

/**
 * Calculates the current SLA state of an order based on elapsed time vs prep time.
 * ON_TIME: < 70% of prep time
 * WARNING: 70–100% of prep time
 * OVERDUE: > 100% of prep time
 */
export function getSLAState(order: KDSOrder): SLAState {
    const createdAt = new Date(order.createdAt).getTime();
    const now = Date.now();
    const elapsedMinutes = (now - createdAt) / (1000 * 60);
    const prepTime = order.prepTimeMinutes || 0;

    if (prepTime === 0) return 'ON_TIME';

    const percentage = (elapsedMinutes / prepTime) * 100;

    if (percentage > 100) return 'OVERDUE';
    if (percentage >= 70) return 'WARNING';
    return 'ON_TIME';
}

/**
 * Returns remaining seconds until prep time is reached.
 */
export function getRemainingSeconds(order: KDSOrder): number {
    const createdAt = new Date(order.createdAt).getTime();
    const prepTimeMs = (order.prepTimeMinutes || 0) * 60 * 1000;
    const targetTime = createdAt + prepTimeMs;
    return Math.max(0, Math.floor((targetTime - Date.now()) / 1000));
}

/**
 * Formats seconds into MM:SS
 */
export function formatDuration(seconds: number): string {
    const absSeconds = Math.abs(seconds);
    const mins = Math.floor(absSeconds / 60);
    const secs = absSeconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
}
